#!/usr/bin/env python3
from pathlib import Path
import uuid,json,re,hashlib
root=Path(__file__).resolve().parents[1]
el=root/'electronics';el.mkdir(parents=True,exist_ok=True)
for f in ['manufacturing','validation','firmware/artifacts','mechanical','references/st','labwired']:(root/f).mkdir(parents=True,exist_ok=True)
libdir=el/'nokia-carrier.pretty';libdir.mkdir(exist_ok=True)
def uid(k):return str(uuid.uuid5(uuid.NAMESPACE_URL,'https://labwired.com/nokia5110-breakout/carrier/rev-a/'+k))
def block(s,start):
 dep=0;ins=False;esc=False
 for i in range(start,len(s)):
  c=s[i]
  if esc:esc=False;continue
  if c=='\\' and ins:esc=True;continue
  if c=='"':ins=not ins
  if not ins:
   if c=='(':dep+=1
   elif c==')':
    dep-=1
    if dep==0:return s[start:i+1]
 raise ValueError('unclosed')
def children(s,key):
 out=[];pos=0
 while True:
  i=s.find('('+key+' ',pos)
  if i<0:return out
  q=block(s,i);out.append(q);pos=i+len(q)
def read_symbol(lib,name):
 s=Path('/usr/share/kicad/symbols/'+lib+'.kicad_sym').read_text();return block(s,s.index('(symbol "'+name+'"'))
libspec={'Header10':('Connector_Generic','Conn_01x10'),'Header8':('Connector_Generic','Conn_01x08'),'Header4':('Connector_Generic','Conn_01x04'),'R':('Device','R'),'C':('Device','C'),'TestPoint':('Connector','TestPoint'),'MountingHole':('Mechanical','MountingHole'),'AccessHole':('Mechanical','MountingHole')}
syms={};pins={}
for local,(lib,name)in libspec.items():
 s=read_symbol(lib,name).replace('(symbol "'+name+'"','(symbol "'+local+'"',1).replace('(symbol "'+name+'_','(symbol "'+local+'_');syms[local]=s;pins[local]={}
 for q in children(s,'pin'):
  n=re.search(r'\(number "([^"]+)"',q);a=re.search(r'\(at ([\d.-]+) ([\d.-]+) ([\d.-]+)\)',q)
  if n and a:pins[local][n[1]]=tuple(float(x)for x in a.groups())
fp_spec={'Header10':('Connector_PinHeader_2.54mm','PinHeader_1x10_P2.54mm_Vertical'),'Header8':('Connector_PinHeader_2.54mm','PinHeader_1x08_P2.54mm_Vertical'),'Header4':('Connector_PinHeader_2.54mm','PinHeader_1x04_P2.54mm_Vertical'),'R':('Resistor_SMD','R_0603_1608Metric'),'C':('Capacitor_SMD','C_0603_1608Metric'),'C0805':('Capacitor_SMD','C_0805_2012Metric'),'TestPoint':('TestPoint','TestPoint_Pad_D1.5mm'),'MountingHole':('MountingHole','MountingHole_2.7mm_M2.5'),'AccessHole':('MountingHole','MountingHole_2.7mm_M2.5')}
fp_provenance=[]
for local,(lib,name)in fp_spec.items():
 original=(Path('/usr/share/kicad/footprints')/(lib+'.pretty')/(name+'.kicad_mod')).read_text();s=original.replace('(footprint "'+name+'"','(footprint "'+local+'"',1)
 for m in children(s,'model'):s=s.replace(m,'')
 if local=='MountingHole':s=s.replace('(drill 2.7)','(drill 2.9)').replace('2.7mm','2.9mm').replace('(end 2.45 0)','(end 3.5 0)')
 if local=='AccessHole':s=s.replace('(drill 2.7)','(drill 10)').replace('(size 2.7 2.7)','(size 10 10)').replace('2.7mm','10mm').replace('(end 2.7 0)','(end 5 0)').replace('(end 2.95 0)','(end 5.6 0)').replace('Mounting Hole 10mm, M2.5, no annular, generated by kicad-footprint-generator mountinghole.py','10 mm NPTH for Nucleo USER/RESET button access; no fastener').replace('mountinghole M2.5','button access NPTH').replace('MountingHole_10mm_M2.5','Button_access_10mm_NPTH')
 (libdir/(local+'.kicad_mod')).write_text(s)
 fp_provenance.append({'local':local,'upstream':lib+'.pretty/'+name+'.kicad_mod','upstream_sha256':hashlib.sha256(original.encode()).hexdigest()})
(el/'nokia-carrier.kicad_sym').write_text('(kicad_symbol_lib (version 20251024) (generator "kicad_symbol_editor")\n'+'\n'.join(syms.values())+'\n)\n')
(el/'sym-lib-table').write_text('(sym_lib_table (version 7) (lib (name "nokia-carrier") (type "KiCad") (uri "${KIPRJMOD}/nokia-carrier.kicad_sym") (options "") (descr "Project-local KiCad symbols")))\n')
(el/'fp-lib-table').write_text('(fp_lib_table (version 7) (lib (name "nokia-carrier") (type "KiCad") (uri "${KIPRJMOD}/nokia-carrier.pretty") (options "") (descr "Project-local KiCad footprints")))\n')
components=[
 {'ref':'J1','lib':'Header10','value':'CN5 / TSW-110-07-G-S','at':(66.04,67.31),'net':{'1':'LCD_RST_PA9','2':'LCD_DC_PC7','3':'LCD_CE_PB6','4':'LCD_DIN_PA7','6':'LCD_CLK_PA5','7':'GND'},'mpn':'TSW-110-07-G-S','manufacturer':'Samtec'},
 {'ref':'J2','lib':'Header8','value':'CN6 / TSW-108-07-G-S','at':(66.04,119.38),'net':{'4':'+3V3','5':'+5V','6':'GND','7':'GND'},'mpn':'TSW-108-07-G-S','manufacturer':'Samtec'},
 {'ref':'J3','lib':'Header8','value':'CN9 / TSW-108-07-G-S','at':(66.04,172.72),'net':{'7':'ECHO_3V3_PB10','8':'TRIG_PA8'},'mpn':'TSW-108-07-G-S','manufacturer':'Samtec'},
 {'ref':'J4','lib':'Header8','value':'JOY-IT LCD REV2','at':(182.88,67.31),'net':{'1':'GND','2':'GND','3':'+3V3','4':'LCD_CLK_PA5','5':'LCD_DIN_PA7','6':'LCD_DC_PC7','7':'LCD_CE_PB6','8':'LCD_RST_PA9'},'mpn':'TSW-108-07-G-S','manufacturer':'Samtec'},
 {'ref':'J5','lib':'Header4','value':'ADAFRUIT 3942 / HC-SR04','at':(299.72,67.31),'net':{'1':'+5V','2':'TRIG_PA8','3':'ECHO_5V','4':'GND'},'mpn':'TSW-104-07-G-S','manufacturer':'Samtec'},
 {'ref':'R1','lib':'R','value':'10k 1%','at':(264.16,119.38),'net':{'1':'ECHO_5V','2':'ECHO_3V3_PB10'},'mpn':'RC0603FR-0710KL','manufacturer':'Yageo'},
 {'ref':'R2','lib':'R','value':'18k 1%','at':(312.42,119.38),'net':{'1':'ECHO_3V3_PB10','2':'GND'},'mpn':'RC0603FR-0718KL','manufacturer':'Yageo'},
 {'ref':'C1','lib':'C','value':'100nF 50V X7R','at':(139.7,127),'net':{'1':'+3V3','2':'GND'},'mpn':'C1608X7R1H104K080AA','manufacturer':'TDK'},
 {'ref':'C2','lib':'C','value':'100nF 50V X7R','at':(180.34,127),'net':{'1':'+5V','2':'GND'},'mpn':'C1608X7R1H104K080AA','manufacturer':'TDK'},
 {'ref':'C3','lib':'C','footprint':'C0805','value':'10uF 25V X5R','at':(220.98,127),'net':{'1':'+5V','2':'GND'},'mpn':'C2012X5R1E106K125AB','manufacturer':'TDK'}]
for i,n in enumerate(['GND','+3V3','+5V','ECHO_5V','ECHO_3V3_PB10'],1):components.append({'ref':'TP'+str(i),'lib':'TestPoint','value':n,'at':(139.7+38.1*(i-1),180.34),'net':{'1':n}})
for i in range(1,5):components.append({'ref':'H'+str(i),'lib':'MountingHole','value':'M2.5 / 2.9mm NPTH','at':(48.26+60.96*(i-1),231.14),'net':{}})
for i in range(5,7):components.append({'ref':'H'+str(i),'lib':'AccessHole','value':'NUCLEO BUTTON ACCESS / 10mm NPTH','at':(292.1+60.96*(i-5),231.14),'net':{}})
sch_id=uid('schematic');pieces=[]
def effects(size=1.27,just=''):return '(effects (font (size '+str(size)+' '+str(size)+'))'+(' (justify '+just+')' if just else '')+')'
def prop(k,v,x,y,hidden=False):return '(property '+json.dumps(k)+' '+json.dumps(v)+' (at '+f'{x:g} {y:g} 0'+') '+('(hide yes) 'if hidden else '')+effects()+')'
def label(n,x,y):return '(label '+json.dumps(n)+' (at '+f'{x:g} {y:g} 0'+') '+effects(1.27,'left bottom')+' (uuid "'+uid('label/'+n+'/'+str(x)+'/'+str(y))+'"))'
for c in components:
 ref=c['ref'];name=c['lib'];x,y=c['at'];sid=uid('symbol/'+ref);c['uuid']=sid
 p=['(symbol (lib_id "nokia-carrier:'+name+'") (at '+f'{x:g} {y:g} 0'+') (unit 1) (in_bom '+('no'if ref.startswith(('TP','H'))else'yes')+') (on_board yes) (dnp no) (uuid "'+sid+'")']
 off=19.05 if name=='Header10'else 15.24 if name=='Header8'else 10.16 if name=='Header4'else 5.08
 p.extend([prop('Reference',ref,x+5.08,y-off),prop('Value',c['value'],x+5.08,y+off,name=='TestPoint'),prop('Footprint','nokia-carrier:'+c.get('footprint',name),x,y,True)])
 for key in ['mpn','manufacturer']:
  if key in c:p.append(prop('MPN'if key=='mpn'else'Manufacturer',c[key],x,y,True))
 for pin in pins[name]:p.append('(pin "'+pin+'" (uuid "'+uid('pin/'+ref+'/'+pin)+'"))')
 p.append('(instances (project "nokia-carrier" (path "/'+sch_id+'" (reference "'+ref+'") (unit 1))))');pieces.append('\n'.join(p)+')')
 for pin,(px,py,angle)in pins[name].items():
  xx=x+px;yy=y-py
  if pin in c['net']:
   dx=-10.16 if name.startswith('Header')else 0
   dy=-5.08 if name in ['R','C']and pin=='1'else 5.08 if name in ['R','C','TestPoint']else 0
   ex,ey=xx+dx,yy+dy
   if dx or dy:pieces.append('(wire (pts (xy '+f'{xx:g} {yy:g}'+') (xy '+f'{ex:g} {ey:g}'+')) (stroke (width 0) (type default)) (uuid "'+uid('wire/'+ref+'/'+pin)+'"))')
   pieces.append(label(c['net'][pin],ex,ey))
  else:pieces.append('(no_connect (at '+f'{xx:g} {yy:g}'+') (uuid "'+uid('nc/'+ref+'/'+pin)+'"))')
def note(t,x,y,size=1.27):pieces.append('(text '+json.dumps(t)+' (at '+f'{x:g} {y:g} 0'+') '+effects(size,'left top')+' (uuid "'+uid('text/'+t)+'"))')
note('NUCLEO-L476RG / Nokia 5110 Breakout carrier - rev A',25.4,15.24,2.54)
note('USB power via Nucleo ST-LINK. CN6 supplies separate +5V and +3V3 rails.\nJ1/J2/J3 fit on BOTTOM and plug into Nucleo CN5/CN6/CN9.\nKeep ST-LINK, target and Arduino connectors at manufacturer default settings.',25.4,24.13)
note('DISPLAY: JOY-IT SBC-LCD84x48 REV2 ONLY\n1 GND, 2 LIGHT (active low), 3 VCC, 4 CLK,\n5 DIN, 6 DC, 7 CE, 8 RST.\nSupply and all logic 3.3V. REV1 differs.',137.16,87.63)
note('SENSOR: ADAFRUIT 3942 / HC-SR04\n1 VCC (+5V), 2 TRIG (3.3V accepted),\n3 ECHO (5V output), 4 GND.\nDo not connect 5V ECHO to the LCD rail.',264.16,87.63)
note('ECHO divider: 10k upper / 18k lower, both 1%.\n5.0V input -> 3.214V at PB10 nominal.\nAt 5.25V and resistor corners: <=3.399V.\nR2 holds PB10 low with a disconnected sensor.',264.16,142.24)
note('CN5: 1 D8/PA9, 2 D9/PC7, 3 D10/PB6,\n4 D11/PA7, 6 D13/PA5, 7 GND.\nCN6: 4 +3V3, 5 +5V, 6/7 GND.\nCN9: 7 D6/PB10, 8 D7/PA8.\nAll other contacts intentionally isolated.',25.4,196.85)
note('90 x 66 x 1.6mm, two copper layers, four M2.5 mounts.\nJ4/J5 and passives on TOP. C1 close to J4; C2/C3 close to J5.\nPurchased Nucleo, display, sensor, cables and hardware: assembly BOM.\nEngineering candidate: physical assembly and bench qualification pending.',137.16,249)
embedded='\n'.join(s.replace('(symbol "'+n+'"','(symbol "nokia-carrier:'+n+'"',1)for n,s in syms.items())
content='(kicad_sch (version 20260101) (generator "eeschema") (uuid "'+sch_id+'") (paper "A3") (title_block (title "Nokia Breakout Nucleo carrier") (date "2026-11-18") (rev "A") (company "LabWired") (comment 1 "NUCLEO-L476RG / JOY-IT LCD REV2 / HC-SR04 5V"))\n(lib_symbols\n'+embedded+'\n)\n'+'\n'.join(pieces)+'\n(embedded_fonts no)\n)\n'
(el/'nokia-carrier.kicad_sch').write_text(content)
(el/'nokia-carrier.kicad_pro').write_text(json.dumps({'meta':{'filename':'nokia-carrier.kicad_pro','version':1},'board':{'design_settings':{'rules':{'min_clearance':.2,'min_track_width':.25,'min_via_diameter':.6,'min_through_hole_diameter':.3,'min_via_annular_width':.15,'min_copper_edge_clearance':.5,'min_hole_clearance':.25,'min_hole_to_hole':.25},'rule_severities':{},'drc_exclusions':[]}},'net_settings':{'classes':[{'name':'Default','clearance':.2,'track_width':.3,'via_diameter':.6,'via_drill':.3,'bus_width':12,'wire_width':6,'line_style':0,'schematic_color':'rgba(0, 0, 0, 0.000)','pcb_color':'rgba(0, 0, 0, 0.000)'}],'meta':{'version':3}}},indent=2)+'\n')
(el/'provenance.json').write_text(json.dumps({'kicad_version':'10.0.8','footprints':fp_provenance,'symbols':libspec,'license':'CC-BY-SA-4.0 with KiCad design exception','source':'https://www.kicad.org/libraries/license/','changes':'Local names; 2.9 mm mount drills; 10 mm button access holes with 5.6 mm courtyard radius; explicit board rule areas for hardware; generic 3D models removed.'},indent=2)+'\n')
(el/'authoring-metadata.json').write_text(json.dumps({'schematic_uuid':sch_id,'components':components},indent=2)+'\n')
print('Wrote native schematic:',len(content),'bytes')

